function solve(line) {
  const fields = [];
  const currentField = [];
  let inQuotes = false;
  let escaped = false;
  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    if (char === '"') {
      inQuotes = !inQuotes;
      if (inQuotes) {
        currentField.push(char);
      } else {
        if (currentField.length > 0 && currentField[currentField.length - 1] === '"') {
          currentField.pop();
        }
      }
    } else if (char === ',' && !inQuotes) {
      fields.push(currentField.join(''));
      currentField.length = 0;
    } else {
      currentField.push(char);
    }
  }
  if (currentField.length > 0) {
    fields.push(currentField.join(''));
  }
  return fields;
}
